/// <summary>
///     Data Controller class for <c>AVASalesRouteCardReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Controller class for the <c>AVASalesRouteCardReport</c> SSRS Report.
/// </remarks>
internal final class AVASalesRouteCardReportController extends  SrsReportRunController
{
    Args        clsArgs;
    SalesTable  clsSalesTable;
    boolean     clsPreviewMode;

}

Method.Source:
/// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <returns>
///    <c>AVASalesRouteCardReportController</c> as return value
/// </returns>
public static AVASalesRouteCardReportController construct()
{
    return new AVASalesRouteCardReportController();
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>RefRecId</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = clsArgs)
{
    clsArgs = _parmValue;

    return clsArgs;
}

/// <summary>
///    AVA <c>parmSalesTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>SalesTable</c> as type
/// </param>
/// <returns>
///    <c>SalesTable</c> as return value
/// </returns>
public SalesTable parmSalesTable(SalesTable _parmValue = clsSalesTable)
{
    clsSalesTable = _parmValue;

    return clsSalesTable;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVASalesRouteCardReportController controller;

    controller = AVASalesRouteCardReportController::newFromArgs(_args);

    controller.parmReportName(ssrsReportStr(AVASalesRouteCardReport, Report));
    controller.parmDialogCaption("@NDX:SalesOrderInternalRouteCard");
    controller.startOperation();
}

/// <summary>
///    AVA <c>prePromptModifyContract</c> method.
/// </summary>
protected void prePromptModifyContract()
{
    AVASalesRouteCardReportContract contract;

    clsPreviewMode = false;

    contract = this.parmReportContract().parmRdpContract();
    contract.parmSalesTableRefRecId(clsSalesTable.RecId);
    contract.parmSalesId(clsSalesTable.SalesId);
    contract.parmPrintMode(SalesTableMode::Simple);

    // Set the target print destination to Screen if we are previewing the report.
    if(this.parmArgs())
    {
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVASalesRouteCardReportActionPreview))
        {
            clsPreviewMode = true;
        }
        else if(this.parmArgs().menuItemName() == menuItemActionStr(AVASalesRouteCardReportAction))
        {
            clsPreviewMode = false;
        }
        else if(this.parmArgs().menuItemName() == menuItemOutputStr(AVASalesRouteCardReportOutput))
        {
            clsPreviewMode = false;
        }
    }

    if (clsPreviewMode)
    {
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);
    }

    // Don't show the report dialog if Preview
    // and don't save to SysLastValue either.
    this.parmShowDialog(!clsPreviewMode);
    this.parmLoadFromSysLastValue(!clsPreviewMode);
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVASalesRouteCardReportController</c> as return value
/// </returns>
public static AVASalesRouteCardReportController newFromArgs(Args _args)
{
    AVASalesRouteCardReportController   locController;
    Common                              locCommon;
    SalesTable                          locSalesTable;

    //controller = new AVASalesRouteCardReportController();
    locController = AVASalesRouteCardReportController::construct();
    locController.parmArgs(_args);
    locController.parmLoadFromSysLastValue(false);

    if(_args)
    {
        if(_args.record().RecId)
        {
            locCommon = _args.record();
            if(     locCommon.RecId
                &&  locCommon.TableId == tableNum(SalesTable))
            {
                locSalesTable = locCommon;
                locController.parmSalesTable(locSalesTable);
            }
        }
    }

    return locController;
}
